function cmeCompletionAnalyze(){const days=Array.isArray(cmeUnifiedData?.days)?cmeUnifiedData.days:[],cityDays=days.filter(d=>d.type==='city'),transfers=days.filter(d=>d.type==='transfer');const ready=cityDays.filter(d=>d.status==='ready').length,started=cityDays.filter(d=>d.focus||d.notes||d.status==='in-progress'||d.status==='ready').length;const transferFields=transfers.filter(d=>d.transfer?.departure&&d.transfer?.transport&&d.transfer?.arrival).length;const checkItems=transfers.flatMap(d=>Object.values(d.transfer?.checklist||{})),checked=checkItems.filter(Boolean).length;const focus=cityDays.filter(d=>d.focus).length,notes=cityDays.filter(d=>d.notes).length;const total=cityDays.length*3+transfers.length*7;const completed=ready*1.5+focus+notes+transferFields*3+checked;const score=total?Math.min(100,Math.round(completed/total*100)):0;const gaps=[];if(!days.length)gaps.push('Generate a unified itinerary from your multi-city route.');cityDays.forEach(d=>{if(!d.focus)gaps.push('Day '+d.day+' · '+d.city+': add a day focus.');if(!d.notes)gaps.push('Day '+d.day+' · '+d.city+': add notes, activities or reminders.');if(d.status!=='ready')gaps.push('Day '+d.day+' · '+d.city+': mark planning status as Ready when reviewed.');});transfers.forEach(d=>{if(!d.transfer?.departure)gaps.push('Day '+d.day+' transfer: add departure plan.');if(!d.transfer?.transport)gaps.push('Day '+d.day+' transfer: specify transport mode.');if(!d.transfer?.arrival)gaps.push('Day '+d.day+' transfer: add arrival plan.');Object.entries({tickets:'tickets / transport',hotel:'accommodation dates',luggage:'luggage / buffer',arrivalPlan:'arrival / last-mile'}).forEach(([k,label])=>{if(!d.transfer?.checklist?.[k])gaps.push('Day '+d.day+' transfer: check '+label+'.');});});return{days,cityDays,transfers,ready,started,transferFields,checked,checkItems,focus,notes,score,gaps};}function cmeCompletionRefresh(){const box=document.getElementById('cme-completion-dashboard'),g=document.getElementById('cme-completion-gaps');if(!box||!g)return;const a=cmeCompletionAnalyze();if(!a.days.length){box.innerHTML='<p>Generate a unified itinerary to review completion status.</p>';g.innerHTML='';return;}box.innerHTML=`<div class="cme-completion-score"><strong>${a.score}%</strong><div><b>Planning completion</b><div>${a.ready} of ${a.cityDays.length} city days marked Ready · ${a.transfers.length} transfer days</div></div></div><div class="cme-completion-metrics"><div class="cme-completion-metric"><strong>${a.days.length}</strong>Total days</div><div class="cme-completion-metric"><strong>${a.cityDays.length}</strong>City days</div><div class="cme-completion-metric"><strong>${a.started}/${a.cityDays.length}</strong>City days started</div><div class="cme-completion-metric"><strong>${a.checked}/${a.checkItems.length}</strong>Transfer checks</div></div>`;g.innerHTML=a.gaps.length?'<h3>Recommended next steps ('+a.gaps.length+')</h3><ul>'+a.gaps.map(x=>'<li class="cme-completion-gap">'+escapeHtml(x)+'</li>').join('')+'</ul>':'<p class="cme-completion-ready">✓ All planning fields reviewed. Still verify bookings and official travel information independently.</p>';}function cmeCompletionExportJSON(){const a=cmeCompletionAnalyze();if(!a.days.length){alert('Generate a unified itinerary first.');return;}const payload={product:'China Made Easy',exportedAt:new Date().toISOString(),completionScore:a.score,route:cmeMultiStops,unifiedItinerary:cmeUnifiedData,planningGaps:a.gaps,disclaimer:'Planning export only. Not live booking, schedule, entry, safety or official travel information.'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='china-made-easy-trip-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}function cmeCompletionPrint(){const a=cmeCompletionAnalyze();if(!a.days.length){alert('Generate a unified itinerary first.');return;}const rows=a.days.map(d=>d.type==='transfer'?`<article><h2>Day ${d.day} · Transfer: ${escapeHtml(d.city)} → ${escapeHtml(d.toCity)}</h2><p><b>Departure:</b> ${escapeHtml(d.transfer?.departure||'Not set')}</p><p><b>Transport:</b> ${escapeHtml(d.transfer?.transport||'Not set')}</p><p><b>Arrival:</b> ${escapeHtml(d.transfer?.arrival||'Not set')}</p><p><b>Notes:</b> ${escapeHtml(d.notes||'')}</p></article>`:`<article><h2>Day ${d.day} · ${escapeHtml(d.city)}</h2><p><b>Focus:</b> ${escapeHtml(d.focus||'Not planned')}</p><p><b>Status:</b> ${escapeHtml(d.status||'planned')}</p><p><b>Notes:</b> ${escapeHtml(d.notes||'')}</p></article>`).join('');const w=window.open('','_blank');if(!w){alert('Please allow pop-ups to print or save as PDF.');return;}w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>China Made Easy Trip</title><style>body{font:16px Arial,sans-serif;max-width:800px;margin:30px auto;padding:0 20px;color:#222}header{border-bottom:2px solid #3f6e4e;padding-bottom:15px}article{break-inside:avoid;border:1px solid #ddd;border-radius:10px;padding:14px;margin:14px 0}h1{font-size:26px}h2{font-size:18px}small{color:#555}@media print{button{display:none}}</style><style id="phase80-auto-fix">.cme-phase80-panel{margin:12px 0;border:1px solid #d5e3d6;background:#f5faf5;border-radius:13px;padding:12px}.cme-phase80-head{display:flex;justify-content:space-between;gap:10px;align-items:center}.cme-phase80-panel p{font-size:12px;color:var(--muted);margin:5px 0}.cme-phase80-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}.cme-phase80-preview{border:1px solid #dce6dc;background:#fff;border-radius:10px;padding:10px;margin-top:10px}.cme-phase80-preview ul{padding-left:20px;margin:7px 0}.cme-phase80-preview li{margin:7px 0;font-size:13px}.cme-phase80-change{display:grid;grid-template-columns:1fr;gap:3px}.cme-phase80-before{color:#9a5147;text-decoration:line-through}.cme-phase80-after{color:#326f48;font-weight:700}.cme-phase80-status{font-size:12px;color:#326f48;font-weight:700;margin-top:8px}@media(max-width:600px){.cme-phase80-head{align-items:flex-start;flex-direction:column}}</style>
</head><body><header><h1>China Made Easy · Trip Plan</h1><p>${a.days.length} days · ${cmeMultiStops.length} cities · ${a.transfers.length} transfer days · Planning completion ${a.score}%</p><small>Generated ${new Date().toLocaleString()} · Verify all booking and travel details independently.</small></header>${rows}<footer><p>Planning document only. No live schedules, bookings, prices, entry rules or official travel information are verified.</p></footer><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();}
document.addEventListener('input',e=>{if(e.target.closest('#cme-unified-itinerary'))cmeCompletionRefresh();});document.addEventListener('change',e=>{if(e.target.closest('#cme-unified-itinerary'))cmeCompletionRefresh();});document.addEventListener('DOMContentLoaded',cmeCompletionRefresh);